import {seedMemoryScale} from './memory-scale-v0100.mjs';import {refreshEntryIndex} from '../../core/thought-model.js';
export async function seedContextScale(s,{topics,entriesPerTopic}){await seedMemoryScale(s,topics);const base=(await s.repository.transaction(false,t=>t.get('meta','synthetic-memory-scale-template'))).value;for(let n=0;n<topics;n++){const id='memory-scale-topic-'+String(n).padStart(4,'0'),sectionId='memory-scale-section-'+n;for(let start=5;start<entriesPerTopic;start+=100){await s.repository.transaction(true,async t=>{for(let j=start;j<Math.min(entriesPerTopic,start+100);j++){const entryId=id+'-entry-'+j,e={...base.entry,id:entryId,title:'长期记录 '+j,thoughtText:`CONTEXT_DEEP_${n}_${j} 合成长期项目的第 ${j} 次不同决策。`+'保留条件、证据和时间，不把旧观点当成现在的决定。'.repeat(20),sourceRecordIds:[],inputRefs:[],topics:[id],updatedSequence:n*entriesPerTopic+j+1,createdSequence:n*entriesPerTopic+j+1,revision:0,contentRevision:0};refreshEntryIndex(e);await t.put('thoughts',e);await t.put('placements',{...base.placement,id:JSON.stringify([id,1,entryId]),topicId:id,entryId,sectionId,rank:String((j+1)*1024).padStart(12,'0'),sourceRecordIds:[]});}});await new Promise(r=>setTimeout(r,0));}}return {topics,entries:topics*entriesPerTopic};}
